import Queue from 'yocto-queue';

export default function pLimit(concurrency) {
	let rejectOnClear = false;

	if (typeof concurrency === 'object') {
		({concurrency, rejectOnClear = false} = concurrency);
	}

	validateConcurrency(concurrency);

	if (typeof rejectOnClear !== 'boolean') {
		throw new TypeError('Expected `rejectOnClear` to be a boolean');
	}

	const queue = new Queue();
	let activeCount = 0;

	const resumeNext = () => {
		// Process the next queued function if we're under the concurrency limit
		if (activeCount < concurrency && queue.size > 0) {
			activeCount++;
			queue.dequeue().run();
		}
	};

	const next = () => {
		activeCount--;
		resumeNext();
	};

	const run = async (function_, resolve, arguments_) => {
		// Execute the function and capture the result promise
		const result = (async () => function_(...arguments_))();

		// Resolve immediately with the promise (don't wait for completion)
		resolve(result);

		// Wait for the function to complete (success or failure)
		// We catch errors here to prevent unhandled rejections,
		// but the original promise rejection is preserved for the caller
		try {
			await result;
		} catch {}

		// Decrement active count and process next queued function
		next();
	};

	const enqueue = (function_, resolve, reject, arguments_) => {
		const queueItem = {reject};

		// Queue the internal resolve function instead of the run function
		// to preserve the asynchronous execution context.
		new Promise(internalResolve => { // eslint-disable-line promise/param-names
			queueItem.run = internalResolve;
			queue.enqueue(queueItem);
		}).then(run.bind(undefined, function_, resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then

		// Start processing immediately if we haven't reached the concurrency limit
		if (activeCount < concurrency) {
			resumeNext();
		}
	};

	const generator = (function_, ...arguments_) => new Promise((resolve, reject) => {
		enqueue(function_, resolve, reject, arguments_);
	});

	Object.defineProperties(generator, {
		activeCount: {
			get: () => activeCount,
		},
		pendingCount: {
			get: () => queue.size,
		},
		clearQueue: {
			value() {
				if (!rejectOnClear) {
					queue.clear();
					return;
				}

				const abortError = AbortSignal.abort().reason;

				while (queue.size > 0) {
					queue.dequeue().reject(abortError);
				}
			},
		},
		concurrency: {
			get: () => concurrency,

			set(newConcurrency) {
				validateConcurrency(newConcurrency);
				concurrency = newConcurrency;

				queueMicrotask(() => {
					// eslint-disable-next-line no-unmodified-loop-condition
					while (activeCount < concurrency && queue.size > 0) {
						resumeNext();
					}
				});
			},
		},
		map: {
			async value(iterable, function_) {
				const promises = [];

				try {
					Array.from(iterable, (value, index) => {
						const promise = generator(function_, value, index);
						promises.push(promise);
						return promise;
					});
				} catch (error) {
					// The iterable threw, so `Promise.all` never observes the already scheduled promises. Observe them here to avoid unhandled rejections.
					for (const promise of promises) {
						promise.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
					}

					throw error;
				}

				return Promise.all(promises);
			},
		},
	});

	return generator;
}

export function limitFunction(function_, options) {
	const limit = pLimit(options);

	const limitedFunction = (...arguments_) => limit(() => function_(...arguments_));
	Object.defineProperty(limitedFunction, 'clearQueue', {
		value: limit.clearQueue,
	});

	return limitedFunction;
}

function validateConcurrency(concurrency) {
	if (!((Number.isInteger(concurrency) || concurrency === Number.POSITIVE_INFINITY) && concurrency > 0)) {
		throw new TypeError('Expected `concurrency` to be a number from 1 and up');
	}
}

export type LimitFunction = {
	/**
	The number of promises that are currently running.
	*/
	readonly activeCount: number;

	/**
	The number of promises that are waiting to run (i.e. their internal `fn` was not called yet).
	*/
	readonly pendingCount: number;

	/**
	Get or set the concurrency limit.
	*/
	concurrency: number;

	/**
	Discard pending promises that are waiting to run.

	This might be useful if you want to tear down the queue at the end of your program's lifecycle or discard any function calls referencing an intermediary state of your app.

	Note: This does not cancel promises that are already running.

	When `rejectOnClear` is enabled, pending promises are rejected with an `AbortError`.
	This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.
	*/
	clearQueue: () => void;

	/**
	Process an iterable of inputs with limited concurrency.

	The mapper function receives the item value and its index.

	If the iterable throws during iteration, the returned promise rejects with that error. Mapper functions that were already scheduled still run, and their results are discarded.

	This is a convenience function for processing inputs that arrive in batches. For more complex use cases, see [p-map](https://github.com/sindresorhus/p-map).

	@param iterable - An iterable containing an argument for the given function.
	@param mapperFunction - Promise-returning/async function.
	@returns A promise equivalent to `Promise.all(Array.from(iterable, (item, index) => limit(mapperFunction, item, index)))`.
	*/
	map: <Input, ReturnType> (
		iterable: Iterable<Input>,
		mapperFunction: (input: Input, index: number) => PromiseLike<ReturnType> | ReturnType
	) => Promise<ReturnType[]>;

	/**
	@param fn - Promise-returning/async function.
	@param arguments - Any arguments to pass through to `fn`. Support for passing arguments on to the `fn` is provided in order to be able to avoid creating unnecessary closures. You probably don't need this optimization unless you're pushing a *lot* of functions.

	Warning: Avoid calling the same `limit` function inside a function that is already limited by it. This can create a deadlock where inner tasks never run. Use a separate limiter for inner tasks.

	@returns The promise returned by calling `fn(...arguments)`.
	*/
	<Arguments extends unknown[], ReturnType>(
		function_: (...arguments_: Arguments) => PromiseLike<ReturnType> | ReturnType,
		...arguments_: Arguments
	): Promise<ReturnType>;
};

/**
Run multiple promise-returning & async functions with limited concurrency.

@param concurrency - Concurrency limit. Minimum: `1`. You can pass a number or an options object with a `concurrency` property.
@returns A `limit` function.

@example
```
import pLimit from 'p-limit';

const limit = pLimit(1);

const input = [
	limit(() => fetchSomething('foo')),
	limit(() => fetchSomething('bar')),
	limit(() => doSomething())
];

// Only one promise is run at once
const result = await Promise.all(input);
console.log(result);
```

@example
```
import pLimit from 'p-limit';

const limit = pLimit({concurrency: 1});
```
*/
export default function pLimit(concurrency: number | Options): LimitFunction;

export type Options = {
	/**
	Concurrency limit.

	Minimum: `1`.
	*/
	readonly concurrency: number;

	/**
	Reject pending promises with an `AbortError` when `clearQueue()` is called.

	Default: `false`.

	This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.
	*/
	readonly rejectOnClear?: boolean;
};

/**
Returns a function with limited concurrency.

The returned function manages its own concurrent executions, allowing you to call it multiple times without exceeding the specified concurrency limit.

Ideal for scenarios where you need to control the number of simultaneous executions of a single function, rather than managing concurrency across multiple functions.

@param function_ - Promise-returning/async function.
@return Function with limited concurrency.

@example
```
import {limitFunction} from 'p-limit';

const limitedFunction = limitFunction(async () => {
	return doSomething();
}, {concurrency: 1});

const input = Array.from({length: 10}, limitedFunction);

// Only one promise is run at once.
await Promise.all(input);
```
*/
export function limitFunction<Arguments extends unknown[], ReturnType>(
	function_: (...arguments_: Arguments) => PromiseLike<ReturnType>,
	options: Options
): ((...arguments_: Arguments) => Promise<ReturnType>) & Pick<LimitFunction, 'clearQueue'>;

import process from 'node:process';
import {AsyncLocalStorage} from 'node:async_hooks';
import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import inRange from 'in-range';
import timeSpan from 'time-span';
import randomInt from 'random-int';
import pLimit, {limitFunction} from './index.js';

test('concurrency: 1', async t => {
	const input = [
		[10, 300],
		[20, 200],
		[30, 100],
	];

	const end = timeSpan();
	const limit = pLimit(1);

	const mapper = ([value, ms]) => limit(async () => {
		await delay(ms);
		return value;
	});

	t.deepEqual(await Promise.all(input.map(x => mapper(x))), [10, 20, 30]);
	t.true(inRange(end(), {start: 590, end: 650}));
});

test('concurrency: 4', async t => {
	const concurrency = 5;
	let running = 0;

	const limit = pLimit(concurrency);

	const input = Array.from({length: 100}, () => limit(async () => {
		running++;
		t.true(running <= concurrency);
		await delay(randomInt(30, 200));
		running--;
	}));

	await Promise.all(input);
});

test('propagates async execution context properly', async t => {
	const concurrency = 2;
	const limit = pLimit(concurrency);
	const store = new AsyncLocalStorage();

	const checkId = async id => {
		await Promise.resolve();
		t.is(id, store.getStore()?.id);
	};

	const startContext = async id => store.run({id}, () => limit(checkId, id));

	await Promise.all(Array.from({length: 100}, (_, id) => startContext(id)));
});

test('non-promise returning function', async t => {
	await t.notThrowsAsync(async () => {
		const limit = pLimit(1);
		await limit(() => null);
	});
});

test('continues after sync throw', async t => {
	const limit = pLimit(1);
	let ran = false;

	const promises = [
		limit(() => {
			throw new Error('err');
		}),
		limit(() => {
			ran = true;
		}),
	];

	try {
		await Promise.all(promises);
	} catch {}

	t.is(ran, true);
});

test('accepts additional arguments', async t => {
	const limit = pLimit(1);
	const symbol = Symbol('test');

	await limit(a => t.is(a, symbol), symbol);
});

test('shared context with a limited provider helper', async t => {
	const limit = pLimit(1);
	const sharedContext = {values: []};

	const runWithContext = (function_, ...arguments_) => limit(function_, sharedContext, ...arguments_);

	const addValue = async (context, value) => {
		context.values.push(value);
		await delay(10);
		return context.values.length;
	};

	const firstPromise = runWithContext(addValue, 'first');
	const secondPromise = runWithContext(addValue, 'second');

	t.is(limit.activeCount, 1);
	t.is(limit.pendingCount, 1);

	const results = await Promise.all([firstPromise, secondPromise]);

	t.deepEqual(results, [1, 2]);
	t.deepEqual(sharedContext.values, ['first', 'second']);
});

test('does not ignore errors', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const promises = [
		limit(async () => {
			await delay(30);
		}),
		limit(async () => {
			await delay(80);
			throw error;
		}),
		limit(async () => {
			await delay(50);
		}),
	];

	await t.throwsAsync(Promise.all(promises), {is: error});
});

test('runs all tasks asynchronously', async t => {
	const limit = pLimit(3);

	let value = 1;

	const one = limit(() => 1);
	const two = limit(() => value);

	t.is(limit.activeCount, 2);

	value = 2;

	const result = await Promise.all([one, two]);

	t.deepEqual(result, [1, 2]);
});

test('activeCount and pendingCount properties', async t => {
	const limit = pLimit(5);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	const runningPromise1 = limit(() => delay(1000));
	t.is(limit.activeCount, 1);
	t.is(limit.pendingCount, 0);

	await runningPromise1;
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	const immediatePromises = Array.from({length: 5}, () => limit(() => delay(1000)));
	const delayedPromises = Array.from({length: 3}, () => limit(() => delay(1000)));

	t.is(limit.activeCount, 5);
	t.is(limit.pendingCount, 3);

	await Promise.all(immediatePromises);
	t.is(limit.activeCount, 3);
	t.is(limit.pendingCount, 0);

	await Promise.all(delayedPromises);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('clearQueue', async t => {
	const limit = pLimit(1);

	Array.from({length: 1}, () => limit(() => delay(1000)));
	Array.from({length: 3}, () => limit(() => delay(1000)));

	await Promise.resolve();
	t.is(limit.pendingCount, 3);
	limit.clearQueue();
	t.is(limit.pendingCount, 0);
});

// Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;

testClearQueueRejects('clearQueue rejects pending promises when enabled', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: true});

	const runningPromise = limit(() => delay(100));
	const pendingPromiseOne = limit(() => delay(10));
	const pendingPromiseTwo = limit(() => delay(10));

	await Promise.resolve();
	t.is(limit.pendingCount, 2);

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await runningPromise;
	await t.throwsAsync(pendingPromiseOne, {name: 'AbortError'});
	await t.throwsAsync(pendingPromiseTwo, {name: 'AbortError'});
});

testClearQueueRejects('limitFunction exposes clearQueue', async t => {
	const limitedFunction = limitFunction(() => delay(20), {concurrency: 1, rejectOnClear: true});

	const runningPromise = limitedFunction();
	const pendingPromise = limitedFunction();

	limitedFunction.clearQueue();

	await runningPromise;
	await t.throwsAsync(pendingPromise, {name: 'AbortError'});
});

test('map', async t => {
	const limit = pLimit(1);
	const results = await limit.map([1, 2, 3, 4, 5, 6, 7], input => input + 1);

	t.deepEqual(results, [2, 3, 4, 5, 6, 7, 8]);
});

test('map works when detached from the limit', async t => {
	const limit = pLimit(1);
	const {map} = limit;
	let running = 0;
	let maxRunning = 0;
	const mapper = async input => {
		running++;
		maxRunning = Math.max(maxRunning, running);
		await delay(10);
		running--;
		return input * 2;
	};

	const directResult = limit(mapper, 1);
	const mapResult = map([2, 3], mapper);

	t.deepEqual(await Promise.all([directResult, mapResult]), [2, [4, 6]]);
	t.is(maxRunning, 1);
});

test('map passes index and preserves order with concurrency', async t => {
	const limit = pLimit(3);
	const inputs = [10, 10, 10, 10, 10];

	// eslint-disable-next-line unicorn/no-array-method-this-argument
	const results = await limit.map(inputs, async (value, index) => {
		// Simulate variable async duration per index to shuffle completion order
		await delay((inputs.length - index) * 5);
		return value + index;
	});

	// Results should be in input order and include index
	t.deepEqual(results, [10, 11, 12, 13, 14]);
});

test('map accepts an iterable (set)', async t => {
	const limit = pLimit(2);
	const inputs = new Set([1, 2, 3, 4]);

	const results = await limit.map(inputs, input => input * 2); // eslint-disable-line unicorn/no-array-method-this-argument

	t.deepEqual(results, [2, 4, 6, 8]);
});

test('map accepts an iterable (array iterator)', async t => {
	const limit = pLimit(2);
	const inputs = [1, 2, 3, 4].values();

	const results = await limit.map(inputs, input => input * 2); // eslint-disable-line unicorn/no-array-method-this-argument

	t.deepEqual(results, [2, 4, 6, 8]);
});

test('map accepts array-like inputs', async t => {
	const limit = pLimit(1);
	const inputs = {0: 'a', 1: 'b', length: 2};

	const results = await limit.map(inputs, (value, index) => `${index}:${value}`); // eslint-disable-line unicorn/no-array-method-this-argument

	t.deepEqual(results, ['0:a', '1:b']);
});

test('map does not leave unhandled rejections when the iterable throws', async t => {
	const limit = pLimit(1);
	const error = new Error('Iterator failed');

	function * inputs() {
		yield 1;
		yield 2;
		yield 3;
		throw error;
	}

	await t.throwsAsync(limit.map(inputs(), async value => {
		await delay(10);
		throw new Error(`Mapper ${value} failed`);
	}), {is: error});

	// Wait for the active and queued mappers to reject. AVA fails the run if any rejection is unhandled.
	await limit(() => {});
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('map rejects with the mapper error', async t => {
	const limit = pLimit(2);
	const error = new Error('🦄');

	await t.throwsAsync(limit.map([1, 2, 3], async value => {
		if (value === 2) {
			throw error;
		}

		return value;
	}), {is: error});
});

test('map resolves to an empty array for an empty iterable', async t => {
	const limit = pLimit(1);

	t.deepEqual(await limit.map([], () => t.fail('mapper should not be called')), []);
	t.deepEqual(await limit.map(new Set(), () => t.fail('mapper should not be called')), []);
});

test('map rejects with the iterable error when it throws before the first item', async t => {
	const limit = pLimit(1);
	const error = new Error('Iterator failed');

	const inputs = {
		* [Symbol.iterator]() { // eslint-disable-line require-yield
			throw error;
		},
	};

	await t.throwsAsync(limit.map(inputs, () => t.fail('mapper should not be called')), {is: error}); // eslint-disable-line unicorn/no-array-callback-reference, unicorn/no-array-method-this-argument
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('map rejects immediately with the iterable error and still runs already scheduled tasks', async t => {
	const limit = pLimit(1);
	const error = new Error('Iterator failed');
	const completed = [];

	function * inputs() {
		yield 1;
		yield 2;
		throw error;
	}

	await t.throwsAsync(limit.map(inputs(), async value => {
		await delay(50);
		completed.push(value);
	}), {is: error});

	// The rejection should not wait for the scheduled tasks to finish
	t.deepEqual(completed, []);

	// With concurrency 1, this only runs after the already scheduled tasks
	await limit(() => {});
	t.deepEqual(completed, [1, 2]);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('map passes sequential indexes for a generator', async t => {
	const limit = pLimit(2);

	function * inputs() {
		yield 'a';
		yield 'b';
		yield 'c';
	}

	const results = await limit.map(inputs(), (value, index) => `${index}:${value}`);

	t.deepEqual(results, ['0:a', '1:b', '2:c']);
});

test('accepts options object', async t => {
	const limit = pLimit({concurrency: 1});

	const input = [
		limit(async () => {
			await delay(50);
			return 1;
		}),
		limit(async () => {
			await delay(50);
			return 2;
		}),
	];

	t.deepEqual(await Promise.all(input), [1, 2]);
	t.is(limit.concurrency, 1);
});

test('throws on invalid concurrency argument', t => {
	t.throws(() => {
		pLimit(0);
	});

	t.throws(() => {
		pLimit(-1);
	});

	t.throws(() => {
		pLimit(1.2);
	});

	t.throws(() => {
		pLimit(undefined);
	});

	t.throws(() => {
		pLimit(true);
	});

	t.throws(() => {
		pLimit({});
	});

	t.throws(() => {
		pLimit({concurrency: 0});
	});
});

test('change concurrency to smaller value', async t => {
	const limit = pLimit(4);
	let running = 0;
	const log = [];
	const promises = Array.from({length: 10}).map(() =>
		limit(async () => {
			++running;
			log.push(running);
			await delay(50);
			--running;
		}));
	await delay(0);
	t.is(running, 4);

	limit.concurrency = 2;
	await Promise.all(promises);
	t.deepEqual(log, [1, 2, 3, 4, 2, 2, 2, 2, 2, 2]);
});

test('change concurrency to bigger value', async t => {
	const limit = pLimit(2);
	let running = 0;
	const log = [];
	const promises = Array.from({length: 10}).map(() =>
		limit(async () => {
			++running;
			log.push(running);
			await delay(50);
			--running;
		}));
	await delay(0);
	t.is(running, 2);

	limit.concurrency = 4;
	await Promise.all(promises);
	t.deepEqual(log, [1, 2, 3, 4, 4, 4, 4, 4, 4, 4]);
});

test('limitFunction()', async t => {
	const concurrency = 5;
	let running = 0;

	const limitedFunction = limitFunction(async () => {
		running++;
		t.true(running <= concurrency);
		await delay(randomInt(30, 200));
		running--;
	}, {concurrency});

	const input = Array.from({length: 100}, limitedFunction);

	await Promise.all(input);
});

import {expectType, expectError} from 'tsd';
import pLimit, {limitFunction} from './index.js';

const limit = pLimit(1);
const limitWithRejectOnClear = pLimit({concurrency: 1, rejectOnClear: true});

const input = [
	limit(async () => 'foo'),
	limit(async () => 'bar'),
	limit(async () => undefined),
];

expectType<Promise<Array<string | undefined>>>(Promise.all(input));

expectType<Promise<string>>(limit((_a: string) => '', 'test'));
expectType<Promise<string>>(limit(async (_a: string, _b: number) => '', 'test', 1));

expectType<number>(limit.activeCount);
expectType<number>(limit.pendingCount);

expectType<void>(limit.clearQueue());
expectType<void>(limitWithRejectOnClear.clearQueue());

// LimitFunction should require a Promise-returning function
const lf = limitFunction(async (_a: string) => 'ok', {concurrency: 1});
expectType<Promise<string>>(lf('input'));
expectType<void>(lf.clearQueue());

expectError(limitFunction((_a: string) => 'x', {concurrency: 1}));
expectError(pLimit({concurrency: 1, rejectOnClear: 'nope'}));

// LimitFunction.map accepts iterables
expectType<Promise<string[]>>(limit.map(new Set(['a', 'b', 'c']), async x => x + x));
expectType<Promise<number[]>>(limit.map([1, 2, 3].values(), async x => x * 2));

