import process from 'node:process';
import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when the limiter is already idle', async t => {
	const limit = pLimit(1);

	const idlePromise = limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(idlePromise);
});

test('onIdle is a promise', async t => {
	const limit = pLimit(1);

	const idlePromise = limit.onIdle();
	t.true(idlePromise instanceof Promise);

	await idlePromise;
});

test('onIdle resolves after running jobs settle', async t => {
	const limit = pLimit(1);
	let finished = false;

	const runningPromise = limit(async () => {
		await delay(20);
		finished = true;
	});

	let idleResolved = false;
	const idlePromise = limit.onIdle().then(() => {
		idleResolved = true;
	});

	await delay(5);
	t.false(idleResolved);
	t.false(finished);

	await runningPromise;
	await idlePromise;

	t.true(finished);
	t.true(idleResolved);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle waits for queued jobs that have not started', async t => {
	const limit = pLimit(1);
	const completed = [];

	const promises = [
		limit(async () => {
			await delay(20);
			completed.push(1);
		}),
		limit(async () => {
			await delay(20);
			completed.push(2);
		}),
		limit(async () => {
			await delay(20);
			completed.push(3);
		}),
	];

	t.is(limit.activeCount, 1);
	t.is(limit.pendingCount, 2);

	await limit.onIdle();

	t.deepEqual(completed, [1, 2, 3]);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(promises);
});

test('reserved slots count as active', async t => {
	const limit = pLimit(1);
	let started = false;

	// The slot is reserved synchronously when the job is scheduled, before the
	// wrapped function has actually started running.
	const runningPromise = limit(async () => {
		started = true;
		await delay(20);
	});

	let idleResolved = false;
	const idlePromise = limit.onIdle().then(() => {
		idleResolved = true;
	});

	t.is(limit.activeCount, 1);
	await delay(5);
	t.false(idleResolved);

	await runningPromise;
	await idlePromise;

	t.true(started);
	t.true(idleResolved);
});

test('multiple onIdle waiters all resolve', async t => {
	const limit = pLimit(1);
	const runningPromise = limit(() => delay(20));

	const idlePromises = [
		limit.onIdle(),
		limit.onIdle(),
		limit.onIdle(),
	];

	await Promise.all(idlePromises);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await runningPromise;
});

test('onIdle resolves when a job rejects', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const rejectedPromise = limit(async () => {
		await delay(10);
		throw error;
	});

	const rejectionAssertion = t.throwsAsync(rejectedPromise, {is: error});
	const idlePromise = limit.onIdle();

	await rejectionAssertion;
	await idlePromise;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not resolve early when a job enqueues another job', async t => {
	const limit = pLimit(1);
	const order = [];

	const firstPromise = limit(async () => {
		await delay(10);
		order.push('first');

		const secondPromise = limit(async () => {
			order.push('second');
			await delay(10);
		});

		await secondPromise;
	});

	await limit.onIdle();

	t.deepEqual(order, ['first', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await firstPromise;
});

test('onIdle does not resolve early when a resolved job enqueues another job', async t => {
	const limit = pLimit(1);
	const order = [];

	const firstPromise = limit(async () => {
		await delay(10);
		order.push('first');
	});

	firstPromise.then(async () => {
		order.push('enqueue');
		await limit(async () => {
			order.push('second');
			await delay(10);
		});
	});

	await limit.onIdle();

	t.deepEqual(order, ['first', 'enqueue', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle resolves after clearQueue with rejectOnClear disabled', async t => {
	const limit = pLimit(1);

	const runningPromise = limit(() => delay(30));
	const pendingPromiseOne = limit(() => delay(10));
	const pendingPromiseTwo = limit(() => delay(10));

	await Promise.resolve();
	t.is(limit.pendingCount, 2);

	let idleResolved = false;
	const idlePromise = limit.onIdle().then(() => {
		idleResolved = true;
	});

	limit.clearQueue();
	t.is(limit.pendingCount, 0);
	t.false(idleResolved);

	await idlePromise;
	t.true(idleResolved);
	t.is(limit.activeCount, 0);

	// The discarded promises never settle, but that must not block onIdle.
	let pendingSettled = false;
	pendingPromiseOne.then(() => {
		pendingSettled = true;
	});
	pendingPromiseTwo.then(() => {
		pendingSettled = true;
	});

	await runningPromise;
	await delay(20);
	t.false(pendingSettled);
});

test('clearQueue releases onIdle waiters when the queue is empty and nothing is active', async t => {
	const limit = pLimit(1);

	// Register a waiter while the limiter is idle and then clear an empty queue.
	const idlePromise = limit.onIdle();
	limit.clearQueue();

	await idlePromise;
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

// Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;

testClearQueueRejects('onIdle resolves after clearQueue with rejectOnClear enabled', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: true});

	const runningPromise = limit(() => delay(20));
	const pendingPromiseOne = limit(() => delay(10));
	const pendingPromiseTwo = limit(() => delay(10));

	await Promise.resolve();
	t.is(limit.pendingCount, 2);

	const rejectionOne = t.throwsAsync(pendingPromiseOne, {name: 'AbortError'});
	const rejectionTwo = t.throwsAsync(pendingPromiseTwo, {name: 'AbortError'});
	const idlePromise = limit.onIdle();

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await runningPromise;
	await Promise.all([rejectionOne, rejectionTwo]);
	await idlePromise;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle works while concurrency changes', async t => {
	const limit = pLimit(1);
	const concurrency = 4;

	const promises = Array.from({length: 8}, () => limit(() => delay(20)));

	limit.concurrency = concurrency;
	t.is(limit.concurrency, concurrency);

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(promises);
});

test('limitFunction exposes onIdle', async t => {
	const limitedFunction = limitFunction(async () => {
		await delay(20);
		return 'done';
	}, {concurrency: 1});

	const firstPromise = limitedFunction();
	const secondPromise = limitedFunction();

	let idleResolved = false;
	const idlePromise = limitedFunction.onIdle().then(() => {
		idleResolved = true;
	});

	await delay(5);
	t.false(idleResolved);

	await Promise.all([firstPromise, secondPromise]);
	await idlePromise;

	t.true(idleResolved);
});

test('limitFunction onIdle resolves when already idle', async t => {
	const limitedFunction = limitFunction(async () => 'done', {concurrency: 1});

	await t.notThrowsAsync(limitedFunction.onIdle());
});

test('onIdle can be awaited multiple times sequentially', async t => {
	const limit = pLimit(1);

	await limit(() => delay(10));
	await limit.onIdle();

	await limit(() => delay(10));
	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

